-- GH-143: application_code was generated by SELECT MAX(application_code) + 1 in Java. Three defects.
--   1. Read-modify-write with no lock: two concurrent submits read the same MAX and one died on the
--      unique index, surfacing to the student as "a record with the same unique value already exists".
--   2. The MAX is lexicographic over text, so once APP-2026-1000 existed MAX still returned
--      APP-2026-999 ('9' > '1'). The counter pinned itself and every later submit that year failed.
--   3. Application is tenant-filtered, and admins may submit on a student's behalf, so the MAX a
--      tenant admin saw excluded other tenants' rows and regenerated codes already in use.
--
-- One global sequence replaces all three. It deliberately does not reset per year: a per-year
-- sequence needs either runtime DDL every January or a migration nobody will remember to write.
-- Uniqueness comes from the sequence alone, so the year in the code is decorative.

CREATE SEQUENCE IF NOT EXISTS application_code_seq AS BIGINT START WITH 1 INCREMENT BY 1 NO CYCLE;

-- Start above every numeric suffix the old generator already issued, across all years and tenants,
-- so no new code can collide with an existing row. setval(..., false) makes the next nextval()
-- return exactly this value rather than one past it. The regex skips malformed legacy codes and
-- COALESCE covers an empty table.
--
-- This seed is the one line here that could cause an incident, and it is untestable in CI: Flyway
-- runs against an empty application table, so only the COALESCE branch is ever exercised. If the
-- seed is wrong the failure is loud and non-corrupting, rejected by the unique index at insert.
-- Recover with: SELECT setval('application_code_seq',
--     (SELECT MAX(CAST(substring(application_code from '[0-9]+$') AS BIGINT)) FROM application) + 1, false);
SELECT setval(
    'application_code_seq',
    COALESCE((SELECT MAX(CAST(substring(application_code from '[0-9]+$') AS BIGINT))
              FROM application
              WHERE application_code ~ '^APP-[0-9]{4}-[0-9]+$'), 0) + 1,
    false
);
